//! Independent reference tests for the XXH32/XXH64/XXH3 implementations.
//!
//! Expected values in `audit_support/xxhash_vectors.rs` were generated by the
//! official C library (libxxhash 0.8.3) through `ctypes`; the test data is the
//! deterministic [`pattern`] function below. This checks every length 0..=300
//! for seeded and unseeded hashing, selected large lengths up to 1 MiB, the
//! custom-secret APIs, incremental splits, and the scalar `const` one-shot
//! functions against the runtime SIMD-dispatched ones.

use xxhash::{Checksum, Xxh3_64, Xxh3_128, Xxh32, Xxh64, xxh3_64, xxh3_128, xxh32, xxh64};

#[path = "audit_support/xxhash_vectors.rs"]
mod vectors;

const SEEDS: [u64; 3] = [0, 0x9E37_79B1_85EB_CA8D, 42];
const SECRET_SALT: u64 = 0x5EC3_A7B1_D9E2_F406;

/// Deterministic data generator. The Python generator uses the same algorithm.
fn pattern(len: usize, salt: u64) -> Vec<u8> {
    let mut x = salt ^ 0x9E37_79B9_7F4A_7C15;
    let mut out = Vec::with_capacity(len);
    for _ in 0..len {
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        out.push((x >> 24) as u8);
    }
    out
}

fn pattern_secret() -> [u8; 192] {
    let v = pattern(192, SECRET_SALT);
    let mut s = [0u8; 192];
    s.copy_from_slice(&v);
    s
}

fn stream64<H>(mut make: impl FnMut() -> H, data: &[u8], chunks: &[usize]) -> u64
where
    H: Checksum<Output = u64>,
{
    let mut h = make();
    let mut off = 0;
    for &n in chunks {
        h.update(&data[off..off + n]);
        off += n;
    }
    assert_eq!(off, data.len());
    h.sum()
}

fn stream32<H>(mut make: impl FnMut() -> H, data: &[u8], chunks: &[usize]) -> u32
where
    H: Checksum<Output = u32>,
{
    let mut h = make();
    let mut off = 0;
    for &n in chunks {
        h.update(&data[off..off + n]);
        off += n;
    }
    assert_eq!(off, data.len());
    h.sum()
}

fn stream128<H>(mut make: impl FnMut() -> H, data: &[u8], chunks: &[usize]) -> u128
where
    H: Checksum<Output = u128>,
{
    let mut h = make();
    let mut off = 0;
    for &n in chunks {
        h.update(&data[off..off + n]);
        off += n;
    }
    assert_eq!(off, data.len());
    h.sum()
}

/// Deterministic multi-chunk split that exercises 1-byte, stripe, buffer and
/// block boundaries without relying on an RNG.
fn chunks_for(len: usize) -> Vec<usize> {
    const SIZES: [usize; 16] = [1, 3, 31, 63, 64, 65, 127, 128, 191, 240, 241, 255, 256, 257, 1024, 4096];
    let mut out = Vec::new();
    let mut left = len;
    let mut i = 0;
    while left > 0 {
        let n = SIZES[i % SIZES.len()].min(left);
        out.push(n);
        left -= n;
        i += 1;
    }
    out
}

#[test]
fn xxh32_matches_c_reference_all_small_lengths() {
    for &(len, seed, expected) in vectors::XXH32_SMALL {
        let data = pattern(len, 0);
        let mut h = Xxh32::with_seed(seed);
        h.update(&data);
        assert_eq!(h.sum(), expected, "XXH32 len={len} seed={seed:#x}");
        if seed == 0 {
            assert_eq!(xxh32(&data), expected, "xxh32 const len={len}");
            assert_eq!(Xxh32::checksum(&data), expected, "Xxh32::checksum len={len}");
        }
    }
}

